/**
 * Issue dependencies ("blocked by" links): cycle-safe linking, the completion
 * gate used by status changes, and the unblocked notification.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, assertNotArchived, subscribe, notify
 */
import { subscribe } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as dependencyRepo from "@/server/repositories/issue-dependency-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import { issueResource, requireFound } from "./_support";
import { notify } from "./notification-service";
import type { IssueId, OrgId } from "@/types/common";
import type { Issue, IssueDependency, IssueStatus } from "@/types/issue";
import type { Actor } from "@/types/member";
import type { Unsubscribe } from "@/types/event";

/** Raised when an issue cannot be completed because blockers are still open. */
export class IssueBlockedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly blockerIds: readonly IssueId[]) {
    super(`Issue is blocked by open issues: ${blockerIds.join(", ")}`);
    this.name = "IssueBlockedError";
  }
}

function isClosedStatus(status: IssueStatus): boolean {
  return status === "done" || status === "canceled";
}

function isOpen(issue: Issue): boolean {
  return issue.archivedAt === null && !isClosedStatus(issue.status);
}

async function loadIssues(
  orgId: OrgId,
  ids: readonly IssueId[],
): Promise<Issue[]> {
  const found: Issue[] = [];
  for (const id of ids) {
    const issue = await issueRepo.findIssueById(orgId, id);
    if (issue) found.push(issue);
  }
  return found;
}

/** Blockers of `issueId` that are neither archived nor done/canceled. */
export async function findOpenBlockers(
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  const ids = await dependencyRepo.listBlockerIds(orgId, issueId);
  return (await loadIssues(orgId, ids)).filter(isOpen);
}

/** Throws `IssueBlockedError` when completing `issueId` is not allowed. */
export async function assertNotBlocked(
  orgId: OrgId,
  issueId: IssueId,
): Promise<void> {
  const open = await findOpenBlockers(orgId, issueId);
  if (open.length > 0) throw new IssueBlockedError(open.map((i) => i.id));
}

/** True when `target` is reachable from `start` by following blocked-by links. */
async function reaches(
  orgId: OrgId,
  start: IssueId,
  target: IssueId,
): Promise<boolean> {
  const seen = new Set<IssueId>();
  const stack: IssueId[] = [start];
  while (stack.length > 0) {
    const current = stack.pop() as IssueId;
    if (current === target) return true;
    if (seen.has(current)) continue;
    seen.add(current);
    stack.push(...(await dependencyRepo.listBlockerIds(orgId, current)));
  }
  return false;
}

export async function addBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<IssueDependency> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  const blocker = requireFound(
    await issueRepo.findIssueById(input.orgId, input.blockerId),
    "Issue",
    input.blockerId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);
  assertNotArchived("Issue", blocker.id, blocker);

  if (issue.id === blocker.id) {
    throw new Error("An issue cannot block itself");
  }

  const existing = await dependencyRepo.findDependency(
    input.orgId,
    issue.id,
    blocker.id,
  );
  if (existing) return existing;

  if (await reaches(input.orgId, blocker.id, issue.id)) {
    throw new Error("This dependency would create a cycle");
  }

  return dependencyRepo.insertDependency(
    input.orgId,
    issue.id,
    blocker.id,
    actor.userId,
  );
}

export async function removeBlocker(
  actor: Actor,
  input: { orgId: OrgId; issueId: IssueId; blockerId: IssueId },
): Promise<boolean> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));

  return dependencyRepo.deleteDependency(
    input.orgId,
    input.issueId,
    input.blockerId,
  );
}

export async function listBlockers(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const ids = await dependencyRepo.listBlockerIds(orgId, issueId);
  return (await loadIssues(orgId, ids))
    .filter((blocker) => blocker.archivedAt === null)
    .sort((a, b) => a.number - b.number);
}

/** Notifies assignees of issues that just lost their last open blocker. */
async function notifyUnblocked(
  orgId: OrgId,
  blockerId: IssueId,
  actorId: Actor["userId"] | null,
): Promise<void> {
  const blockedIds = await dependencyRepo.listBlockedIds(orgId, blockerId);
  for (const blocked of await loadIssues(orgId, blockedIds)) {
    if (!isOpen(blocked) || blocked.assigneeId === null) continue;
    if ((await findOpenBlockers(orgId, blocked.id)).length > 0) continue;

    await notify(orgId, "issue_unblocked", [blocked.assigneeId], {
      title: "An issue was unblocked",
      body: `Issue ${blocked.id} has no open blockers left`,
      href: `/issues/${blocked.id}`,
      actorId,
    });
  }
}

export function registerIssueDependencyListeners(): Unsubscribe {
  const offs = [
    subscribe("issue.status_changed", async (payload) => {
      if (isClosedStatus(payload.from) || !isClosedStatus(payload.to)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
    subscribe("issue.archived", async (payload) => {
      const issue = await issueRepo.findIssueById(
        payload.orgId,
        payload.issueId,
      );
      if (!issue || isClosedStatus(issue.status)) return;
      await notifyUnblocked(payload.orgId, payload.issueId, payload.actorId);
    }),
  ];
  return () => {
    for (const off of offs) off();
  };
}
